import {assertFrameRate,type FrameRate} from '@/components/nyc-tron/ui/components/forge/timebase';
import {removeMotionKeys,type MotionPropertyCurve,type MotionKeySelection} from '@/components/nyc-tron/ui/components/forge/motion/motion-curves';
import {motionSelectionKey,validateMotionTimeline,moveMotionSelection} from '@/components/nyc-tron/ui/components/forge/motion/motion-timeline';
