export type {MotionPropertyCurve,MotionKeyframe,MotionKeySelection} from '@/components/nyc-tron/ui/components/forge/motion/motion-curves';
export interface MotionKeyframeTimelineProps extends Omit<ViewProps,'children'> {
 readonly scope:string;readonly revision:string;readonly curves:readonly MotionPropertyCurve[];readonly duration:number;
 readonly selection:readonly MotionKeySelection[];readonly onSelectionChange:(selection:readonly MotionKeySelection[])=>void;
 readonly onCommit:(curves:readonly MotionPropertyCurve[],selection:readonly MotionKeySelection[])=>void;
 readonly onPreview?:(curves:readonly MotionPropertyCurve[]|undefined)=>void;
 readonly viewRange:readonly [number,number];readonly onViewRangeChange:(range:readonly [number,number])=>void;
 readonly playhead:number;readonly onPlayheadChange:(time:number)=>void;readonly frameRate:FrameRate;readonly snapToFrames:boolean;readonly onSnapChange:(enabled:boolean)=>void;
 readonly height?:number;readonly disabled?:boolean;readonly unstyled?:boolean;
}
const LABEL=100,PAD=24,ROW=84;
const signature=(selection:readonly MotionKeySelection[])=>JSON.stringify(selection.map(motionSelectionKey).sort());
const makeStore=()=>createStore(()=>({width:0,mode:'tracks' as 'tracks'|'keys'|'settings',preview:null as readonly MotionPropertyCurve[]|null,error:null as string|null}));
/** Virtualized property lanes and full key list share one controlled selection.
 * Shift adds and Ctrl/Meta toggles; dragging any selected key moves the group. */
export function MotionKeyframeTimeline({scope,revision,curves,duration,selection,onSelectionChange,onCommit,onPreview,viewRange,onViewRangeChange,playhead,onPlayheadChange,frameRate,snapToFrames,onSnapChange,height=320,disabled=false,unstyled=false,...props}:MotionKeyframeTimelineProps){
 validateMotionTimeline(curves,selection,duration);assertFrameRate(frameRate);
 if(!scope.trim()||!viewRange.every(Number.isFinite)||viewRange[0]<0||viewRange[1]>duration||viewRange[1]-viewRange[0]<.000001||!Number.isFinite(playhead)||playhead<0||playhead>duration||!Number.isFinite(height)||height<100||height>4000)throw new RangeError('Invalid keyframe timeline viewport or playhead');
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,s=useStore(store,state=>state);
 const latest=useRef({onCommit,onPreview,disabled});latest.current={onCommit,onPreview,disabled};
 const boundary=JSON.stringify([scope,revision]),committed=useRef<string|null>(null);
 const drag=useRef<{boundary:string;start:readonly MotionPropertyCurve[];next:readonly MotionPropertyCurve[];selection:readonly MotionKeySelection[];anchor:MotionKeySelection;signature:string;moved:boolean}|null>(null);
 const cancel=()=>{if(!drag.current)return;drag.current=null;store.setState({preview:null});latest.current.onPreview?.(undefined);};
 useLayoutEffect(()=>{committed.current=boundary;cancel();store.setState({error:null});return()=>{committed.current=null;cancel();};},[boundary,disabled,viewRange[0],viewRange[1],s.width]);
 const selectedSignature=signature(selection);useLayoutEffect(()=>{if(drag.current&&drag.current.signature!==selectedSignature)cancel();},[selectedSignature]);
 const shown=s.preview??curves,chosen=new Set(selection.map(motionSelectionKey)),span=viewRange[1]-viewRange[0],stageWidth=Math.max(100,(s.width||420)-LABEL),plotWidth=Math.max(1,stageWidth-2*PAD),step=frameRate.denominator/frameRate.numerator;
 const rows=useMemo(()=>s.mode==='keys'?curves.flatMap(curve=>curve.keys.map(key=>({curve,key,ref:{propertyId:curve.id,keyId:key.id}}))):[],[curves,s.mode]);
 const setSelection=(next:readonly MotionKeySelection[])=>{if(disabled)return;onSelectionChange(next);};
 const selectAt=(ref:MotionKeySelection,mods:DragModifiers):readonly MotionKeySelection[]=>{const id=motionSelectionKey(ref),present=chosen.has(id);let next:readonly MotionKeySelection[];
  if(mods.ctrl||mods.meta)next=present?selection.filter(value=>motionSelectionKey(value)!==id):[...selection,ref];else if(mods.shift)next=present?selection:[...selection,ref];else next=present?selection:[ref];
  if(signature(next)!==selectedSignature)setSelection(next);return next;
 };
 const begin=(ref:MotionKeySelection,mods:DragModifiers)=>{if(disabled||committed.current!==boundary)return;if(drag.current){cancel();return;}const next=selectAt(ref,mods);if(!next.some(value=>motionSelectionKey(value)===motionSelectionKey(ref))){drag.current=null;return;}drag.current={boundary,start:curves,next:curves,selection:next,anchor:ref,signature:signature(next),moved:false};store.setState({error:null});};
 const move=(dx:number,dy:number,mods:DragModifiers)=>{const active=drag.current;if(!active||active.boundary!==committed.current||disabled)return;if(!active.moved&&Math.hypot(dx,dy)<3)return;active.moved=true;try{active.next=moveMotionSelection(active.start,active.selection,active.anchor,dx/plotWidth*span*(mods.alt?.1:1),duration,snapToFrames&&!mods.alt?step:0);store.setState({preview:active.next});latest.current.onPreview?.(active.next);}catch(error){cancel();store.setState({error:error instanceof Error?error.message:'Invalid keyframe group move'});}};
 const release=()=>{const active=drag.current;drag.current=null;store.setState({preview:null});latest.current.onPreview?.(undefined);if(active?.moved&&active.boundary===committed.current&&!latest.current.disabled&&JSON.stringify(active.next)!==JSON.stringify(active.start))latest.current.onCommit(active.next,active.selection);};
 const nudge=(ref:MotionKeySelection,direction:-1|1,factor=1,fine=false)=>{if(disabled||committed.current!==boundary)return;const next=chosen.has(motionSelectionKey(ref))?selection:[ref];try{const moved=moveMotionSelection(curves,next,ref,direction*(snapToFrames?step:span/100)*factor,duration,snapToFrames&&!fine?step:0);if(JSON.stringify(moved)!==JSON.stringify(curves))onCommit(moved,next);}catch(error){store.setState({error:error instanceof Error?error.message:'Invalid keyframe move'});}};
 const remove=()=>{if(disabled||!selection.length||committed.current!==boundary)return;const byProperty=new Map<string,string[]>();for(const ref of selection){const ids=byProperty.get(ref.propertyId)??[];ids.push(ref.keyId);byProperty.set(ref.propertyId,ids);}const next=curves.map(curve=>byProperty.has(curve.id)?removeMotionKeys(curve,byProperty.get(curve.id)!):curve);onCommit(next,[]);};
 const keyDown=(ref:MotionKeySelection,event:CanvasKeyEvent)=>{const key=keyboardKey(event);if(key==='Escape'){cancel();return;}if(key!=='ArrowLeft'&&key!=='ArrowRight')return;event.preventDefault?.();const alt=event.altKey??event.nativeEvent?.altKey??false,shift=event.shiftKey??event.nativeEvent?.shiftKey??false;nudge(ref,key==='ArrowRight'?1:-1,alt?.1:shift?10:1,alt);};
 const toggle=(ref:MotionKeySelection)=>setSelection(chosen.has(motionSelectionKey(ref))?selection.filter(value=>motionSelectionKey(value)!==motionSelectionKey(ref)):[...selection,ref]);
 const rootKey=(event:KeyEventLike)=>{const target=(event as {target?:{tagName?:string;isContentEditable?:boolean}}).target;if(target?.tagName==='INPUT'||target?.tagName==='TEXTAREA'||target?.isContentEditable)return;const key=keyboardKey(event);if(key==='Escape')cancel();else if(key==='Delete'||key==='Backspace'){(event as {preventDefault?:()=>void}).preventDefault?.();remove();}};
 return <View {...props} {...{onKeyDown:rootKey}} onLayout={event=>{const width=event.nativeEvent.layout.width;if(width!==store.getState().width){cancel();store.setState({width});}props.onLayout?.(event);}} style={[{gap:space[2]},props.style]}>
  <Text accessibilityLiveRegion="polite" {...{className:joinClasses(!unstyled&&'text-text')}}>{`${selection.length} selected keyframes`}</Text>
  <SegmentedControl aria-label="Keyframe timeline view" value={s.mode} options={[{value:'tracks',label:'Property lanes'},{value:'keys',label:'Key list'},{value:'settings',label:'Timing'}]} disabled={disabled} unstyled={unstyled} onChange={mode=>{cancel();store.setState({mode});}}/>
  {s.mode==='tracks'?<>
   <View pointerEvents="none" style={{flexDirection:'row',paddingLeft:LABEL+PAD,paddingRight:PAD,justifyContent:'space-between'}}>{Array.from({length:5},(_,i)=><Text key={i} {...{className:joinClasses(!unstyled&&'text-text-muted')}}>{Number((viewRange[0]+span*i/4).toFixed(3))}</Text>)}</View>
   <FlatList data={shown} keyExtractor={curve=>curve.id} style={{height}} initialNumToRender={6} windowSize={5} getItemLayout={(_,index)=>({length:ROW,offset:ROW*index,index})} extraData={[selection,s.width,disabled,viewRange,playhead]} accessibilityLabel="Motion property lanes"
    ListEmptyComponent={<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>No animated properties supplied</Text>}
    renderItem={({item:curve})=>{const visible=curve.keys.filter(key=>key.time>=viewRange[0]&&key.time<=viewRange[1]),stride=Math.max(1,Math.ceil(visible.length/Math.max(16,Math.min(128,Math.floor(plotWidth/8)))));const activeAnchor=drag.current?.anchor??selection[0];return <View style={{height:ROW,flexDirection:'row',borderBottomWidth:border[1]}} {...{className:joinClasses(!unstyled&&'border-border')}}>
     <View style={{width:LABEL,justifyContent:'center',padding:space[1]}}><Text numberOfLines={2} {...{className:joinClasses(!unstyled&&'text-text')}}>{curve.label}</Text><Button title="Select track" accessibilityLabel={`Select all ${curve.label} keyframes`} disabled={disabled||!curve.keys.length} unstyled={unstyled} onPress={()=>setSelection(curve.keys.map(key=>({propertyId:curve.id,keyId:key.id})))}/></View>
     <View style={{flex:1,height:ROW,position:'relative',overflow:'hidden',direction:'ltr'}}>
      {playhead>=viewRange[0]&&playhead<=viewRange[1]?<View pointerEvents="none" style={{position:'absolute',left:PAD+(playhead-viewRange[0])/span*plotWidth,width:1,top:0,bottom:0}} {...{className:joinClasses(!unstyled&&'bg-text-muted')}}/>:null}
      {visible.filter((key,i)=>i%stride===0||activeAnchor?.propertyId===curve.id&&activeAnchor.keyId===key.id).map(key=>{const ref={propertyId:curve.id,keyId:key.id},selected=chosen.has(motionSelectionKey(ref)),at={x:PAD+(key.time-viewRange[0])/span*plotWidth,y:ROW/2};return disabled?<View key={key.id} style={{position:'absolute',left:at.x-4,top:at.y-4,width:8,height:8}} {...{className:joinClasses(!unstyled&&'bg-text-muted')}}/>:<CanvasKnob key={key.id} at={at} selected={selected} styled={!unstyled} testID={`motion-key-${curve.id}-${key.id}`} label={`${curve.label} key ${key.id}, ${key.time} seconds`} hint="Drag selected keys together. Shift adds; Control or Command toggles. Arrow keys move the selection." actions={[{name:'activate',label:'Select key'},{name:'increment',label:'Move later'},{name:'decrement',label:'Move earlier'}]} onAction={name=>{if(name==='activate')setSelection([ref]);else if(name==='increment'||name==='decrement')nudge(ref,name==='increment'?1:-1);}} onKeyDown={event=>keyDown(ref,event)} onBegin={mods=>begin(ref,mods)} onMove={move} onRelease={release} onCancel={cancel}><View pointerEvents="none" style={{width:10,height:10,transform:[{rotate:'45deg'}]}} {...{className:joinClasses(!unstyled&&(selected?'bg-accent':'bg-text-muted'))}}/></CanvasKnob>;})}
     </View>
    </View>;}}/>
  </>:s.mode==='keys'?<FlatList data={rows} keyExtractor={row=>motionSelectionKey(row.ref)} style={{height}} initialNumToRender={12} windowSize={5} accessibilityLabel="All property keyframes" extraData={[selection,disabled]} renderItem={({item})=><Pressable accessibilityRole="checkbox" accessibilityLabel={`Select ${item.curve.label} key ${item.key.id}`} accessibilityState={{checked:chosen.has(motionSelectionKey(item.ref)),disabled}} aria-checked={chosen.has(motionSelectionKey(item.ref))} disabled={disabled} onPress={()=>toggle(item.ref)} style={{minHeight:48,padding:space[2]}}><Text {...{className:joinClasses(!unstyled&&'text-text')}}>{`${item.curve.label}: ${item.key.time}s, ${item.key.value}`}</Text></Pressable>}/>:null}
  {s.mode==='settings'?<ScrollView style={{height}} contentContainerStyle={{gap:space[2]}} keyboardShouldPersistTaps="handled">
  <SettingSwitch label="Snap motion keys to frames" on={snapToFrames} onChange={enabled=>{if(!disabled)onSnapChange(enabled);}} disabled={disabled} styled={!unstyled}/>
  <UnitInput scope={scope} label="Motion playhead seconds" value={playhead} min={0} max={duration} step={step} precision={6} disabled={disabled} unstyled={unstyled} onCommit={time=>{if(!disabled)onPlayheadChange(time);}}/>
  <UnitInput scope={scope} label="Timeline view start seconds" value={viewRange[0]} min={0} max={viewRange[1]-.000001} precision={6} disabled={disabled} unstyled={unstyled} onCommit={time=>{if(!disabled)onViewRangeChange([time,viewRange[1]]);}}/>
  <UnitInput scope={scope} label="Timeline view end seconds" value={viewRange[1]} min={viewRange[0]+.000001} max={duration} precision={6} disabled={disabled} unstyled={unstyled} onCommit={time=>{if(!disabled)onViewRangeChange([viewRange[0],time]);}}/>
  </ScrollView>:null}
  <View style={{flexDirection:'row',flexWrap:'wrap',gap:space[1.5]}}><Button title="Delete selected motion keys" disabled={disabled||!selection.length} unstyled={unstyled} onPress={remove}/><Button title="Clear keyframe selection" disabled={disabled||!selection.length} unstyled={unstyled} onPress={()=>setSelection([])}/></View>
  {s.error?<Text accessibilityLiveRegion="polite" {...{className:joinClasses(!unstyled&&'text-danger')}}>{s.error}</Text>:null}
 </View>;
}

/**
 * Small pieces shared by the vector-tools components: a straight overlay line
 * drawn as a rotated view (the PatchGraph wire technique, since the package has
 * no SVG dependency), and a command button that stays pressable while
 * unavailable so it can say why in the cluster's notice line.
 */
import {useRef,type ReactNode} from "react";
import {PanResponder,Pressable,Text,View,type GestureResponderEvent} from "react-native";
import {createCanvasResponder} from "@/components/nyc-tron/ui/components/gestures/canvas-responder";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import type {Point} from "@/components/nyc-tron/ui/components/forge/vector/vector-types";
import {space,font,opacity as opacityToken} from "@/components/nyc-tron/ui/tokens";

/** Every vector-tools control target is at least this many points square. */
export const VECTOR_TOUCH_TARGET=44;

/** A straight line between two view points, never a touch target. */
export function LinePiece({from,to,thickness=2,className,color,opacity=1}:{
  from:Point;to:Point;thickness?:number;className?:string|undefined;color?:string|undefined;opacity?:number;
}){
  const dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy);
  if(len<0.01)return null;
  return <View pointerEvents="none" {...{className}}
    style={{position:"absolute",left:(from.x+to.x-len)/2,top:(from.y+to.y)/2-thickness/2,width:len,height:thickness,
      opacity,...(color?{backgroundColor:color}:null),transform:[{rotate:Math.atan2(dy,dx)*180/Math.PI+"deg"}]}}/>;
}

/**
 * Command button for the vector tools. When `reason` is set the button reads
 * as unavailable but still takes the press and reports the reason instead of
 * running, so nothing is silently dead.
 */
export function VectorButton({label,reason,onPress,onBlocked,role="button",checked,styled,children,testID}:{
  label:string;reason?:string|undefined;onPress:()=>void;onBlocked:(reason:string)=>void;
  role?:"button"|"radio"|"switch";checked?:boolean;styled:boolean;children?:ReactNode;testID?:string;
}){
  const disabled=reason!==undefined;
  const on=checked===true;
  // React Native Web's Pressable overwrites aria-disabled with its own
  // `disabled` prop, which would swallow the press; "unavailable" in the name
  // carries the state on web and accessibilityState carries it natively.
  return <Pressable role={role} aria-label={disabled?label+", unavailable":label} testID={testID}
    aria-checked={role==="button"?undefined:on} accessibilityState={{disabled,...(role==="button"?{}:{checked:on})}}
    accessibilityHint={reason}
    onPress={()=>{if(reason!==undefined)onBlocked(reason);else onPress();}}
    {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
      styled&&(on?"border-primary bg-primary":"border-border bg-surface-raised"))}}
    style={{minWidth:VECTOR_TOUCH_TARGET,minHeight:VECTOR_TOUCH_TARGET,paddingHorizontal:space[3],
      flexDirection:"row",alignItems:"center",justifyContent:"center",gap:space[1.5],opacity:disabled?opacityToken[50]:1}}>
    {children}
    <Text numberOfLines={1} {...{className:joinClasses(styled&&(on?"text-on-primary":"text-text"))}}
      style={{fontSize:font[13],fontWeight:on?"700":"500"}}>{label}</Text>
  </Pressable>;
}

/** Polite status line: hints, and the reason an unavailable command did not run. */
export function NoticeLine({text,styled,testID}:{text:string|undefined;styled:boolean;testID?:string}){
  return <Text accessibilityLiveRegion="polite" aria-live="polite" testID={testID}
    {...{className:joinClasses(styled&&"text-text-muted text-xs")}} style={{minHeight:18}}>{text??""}</Text>;
}

/** Group heading inside an inspector or bar. */
export function GroupLabel({children,styled,nativeID}:{children:string;styled:boolean;nativeID?:string}){
  return <Text accessibilityRole="header" nativeID={nativeID}
    {...{className:joinClasses(styled&&"text-text text-xs font-semibold")}}>{children}</Text>;
}

/** Modifier keys seen during a canvas drag. React Native Web reports Shift; Alt comes from key tracking. */
export interface DragModifiers {
  readonly alt:boolean;
  readonly shift:boolean;
  readonly ctrl?:boolean;
  readonly meta?:boolean;
}
/** Keyboard event shape on web (`key`, modifiers) and native (`nativeEvent`). */
export type CanvasKeyEvent={
  key?:string;shiftKey?:boolean;altKey?:boolean;preventDefault?:()=>void;
  nativeEvent?:{key?:string;shiftKey?:boolean;altKey?:boolean};
};
/** Props for {@linkcode CanvasKnob}. */
export interface CanvasKnobProps {
  /** Centre in overlay points. */
  at:Point;
  testID:string;
  label:string;
  hint:string;
  selected:boolean;
  actions:readonly {name:string;label:string}[];
  onAction:(name:string)=>void;
  onKeyDown:(event:CanvasKeyEvent)=>void;
  onFocus?:()=>void;
  onBegin:(modifiers:DragModifiers)=>void;
  /** View-space travel since the press. Preview only. */
  onMove:(dx:number,dy:number,modifiers:DragModifiers)=>void;
  onRelease:()=>void;
  onCancel:()=>void;
  /** Drawn marker, centred in the 44pt target. */
  children:ReactNode;
  zIndex?:number;
  styled:boolean;
}
/**
 * A 44pt draggable, focusable target centred on an on-canvas point. A second
 * pointer or OS termination cancels; a parent scroll view cannot steal it.
 */
export function CanvasKnob(props:CanvasKnobProps){
  const {at,testID,label,hint,selected,actions,onAction,onKeyDown,onFocus,children,zIndex=1,styled}=props;
  const latest=useRef(props);
  latest.current=props;
  const pan=useRef<ReturnType<typeof PanResponder.create>|null>(null);
  if(!pan.current)pan.current=createCanvasResponder({
    onStartShouldSetPanResponder:e=>(e.nativeEvent.touches?.length??1)<=1,
    onMoveShouldSetPanResponder:()=>true,
    onPanResponderGrant:e=>{const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean};latest.current.onBegin({alt:n.altKey===true,shift:n.shiftKey===true,ctrl:n.ctrlKey===true,meta:n.metaKey===true});},
    onPanResponderMove:(e:GestureResponderEvent,g)=>{
      if(g.numberActiveTouches>1){latest.current.onCancel();return;}
      const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean};
      latest.current.onMove(g.dx,g.dy,{alt:n.altKey===true,shift:n.shiftKey===true});
    },
    onPanResponderRelease:()=>latest.current.onRelease(),
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>latest.current.onCancel(),
  });
  return <View {...pan.current.panHandlers} accessible testID={testID}
    accessibilityRole="button" accessibilityLabel={label} accessibilityHint={hint}
    accessibilityState={{selected}} accessibilityActions={actions}
    onAccessibilityAction={e=>onAction(e.nativeEvent.actionName)}
    {...{onKeyDown,focusable:true,onFocus,
      className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{position:"absolute",left:at.x-VECTOR_TOUCH_TARGET/2,top:at.y-VECTOR_TOUCH_TARGET/2,
      width:VECTOR_TOUCH_TARGET,height:VECTOR_TOUCH_TARGET,alignItems:"center",justifyContent:"center",zIndex}}>
    {children}
  </View>;
}

import {PanResponder,Platform,type GestureResponderEvent,type PanResponderCallbacks,type PanResponderGestureState} from "react-native";

type Pointer = {
  pointerId:number;button:number;isPrimary?:boolean;clientX:number;clientY:number;pageX:number;pageY:number;
  altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean;
};
type Surface = {
  focus?(options?:{preventScroll?:boolean}):void;
  getBoundingClientRect():{left:number;top:number};
  setPointerCapture(id:number):void;
  releasePointerCapture(id:number):void;
  hasPointerCapture(id:number):boolean;
};
type PointerEvent = {
  nativeEvent:Pointer;currentTarget:Surface;
  preventDefault():void;
};

/**
 * Canvas gesture transport. Native keeps PanResponder. Web uses actual pointer
 * capture because RN Web deliberately excludes Alt/Ctrl mouse presses from its
 * responder system, while canvas tools need those modifiers for editing.
 * Pointer positions are normalized to the same local/page coordinate contract.
 */
export function createCanvasResponder(config:PanResponderCallbacks):ReturnType<typeof PanResponder.create>{
  if(Platform.OS!=="web")return PanResponder.create(config);
  let active:{id:number;surface:Surface;x:number;y:number;pageX:number;pageY:number}|undefined;
  const normalize=(event:PointerEvent):[GestureResponderEvent,PanResponderGestureState]=>{
    const n=event.nativeEvent,rect=event.currentTarget.getBoundingClientRect();
    const start=active??{x:n.clientX,y:n.clientY,pageX:n.pageX,pageY:n.pageY};
    const nativeEvent={...n,locationX:n.clientX-rect.left,locationY:n.clientY-rect.top,
      altKey:n.altKey,shiftKey:n.shiftKey,ctrlKey:n.ctrlKey,metaKey:n.metaKey,
